#include "stdlib/lapack/base/dlantr.h"
#include "stdlib/math/base/special/abs.h"
#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/constants/float64/nan.h"
#include "stdlib/constants/float64/pinf.h"
#include <stdbool.h>

/**
* Computes a norm of a triangular or trapezoidal matrix using alternative indexing semantics.
*
* ## Notes
*
* -   Adapted from LAPACK's DLANTR; see the accompanying NOTICE.
* -   Frobenius accumulation uses scaled sums of squares, independently of DLASSQ's interface.
*
* @param norm        norm type: M, 1/O, I, or F/E (case-insensitive)
* @param uplo        upper or lower trapezoidal storage
* @param diag        unit or non-unit diagonal
* @param M           number of rows
* @param N           number of columns
* @param A           input matrix
* @param strideA1    row stride
* @param strideA2    column stride
* @param offsetA     matrix offset
* @param work        infinity norm scratch storage
* @param strideWork  workspace stride
* @param offsetWork  workspace offset
* @return            norm (NaN for invalid options or dimensions)
*/
double API_SUFFIX(c_dlantr_ndarray)( const char norm, const LAPACK_UPLO uplo, const LAPACK_DIAGONAL diag, const LAPACK_INT M, const LAPACK_INT N, const double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, double *work, const LAPACK_INT strideWork, const LAPACK_INT offsetWork ) {
	LAPACK_INT start;
	LAPACK_INT stop;
	LAPACK_INT i;
	LAPACK_INT j;
	double sumsq;
	double scale;
	double value;
	double sum;
	double ax;
	double r;
	bool unit;
	char n;

	n = norm;
	if ( n == 'm' ) {
		n = 'M';
	} else if ( n == 'O' || n == 'o' ) {
		n = '1';
	} else if ( n == 'i' ) {
		n = 'I';
	} else if ( n == 'f' || n == 'E' || n == 'e' ) {
		n = 'F';
	}
	if ( n != 'M' && n != '1' && n != 'I' && n != 'F' ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( diag != LAPACK_UNIT_DIAGONAL && diag != LAPACK_NON_UNIT_DIAGONAL ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( M < 0 || N < 0 || ( uplo == LAPACK_UPPER_TRIANGLE && M > N ) || ( uplo == LAPACK_LOWER_TRIANGLE && N > M ) ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( M == 0 || N == 0 ) {
		return 0.0;
	}
	if ( n == 'I' && strideWork == 0 ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	unit = ( diag == LAPACK_UNIT_DIAGONAL );
	value = 0.0;
	scale = 0.0;
	sumsq = 1.0;
	if ( n == 'I' ) {
		for ( i = 0; i < M; i++ ) {
			work[ offsetWork+(i*strideWork) ] = 0.0;
		}
	}
	for ( j = 0; j < N; j++ ) {
		if ( uplo == LAPACK_UPPER_TRIANGLE ) {
			start = 0;
			stop = ( j < M ) ? j : M-1;
		} else {
			start = j;
			stop = M-1;
		}
		sum = 0.0;
		for ( i = start; i <= stop; i++ ) {
			ax = ( unit && i == j ) ? 1.0 : stdlib_base_abs( A[ offsetA+(i*strideA1)+(j*strideA2) ] );
			if ( n == 'M' ) {
				if ( ax > value || stdlib_base_is_nan( ax ) ) {
					value = ax;
				}
			} else if ( n == '1' ) {
				sum += ax;
			} else if ( n == 'I' ) {
				work[ offsetWork+(i*strideWork) ] += ax;
			} else {
				if ( stdlib_base_is_nan( ax ) ) {
					return STDLIB_CONSTANT_FLOAT64_NAN;
				}
				if ( ax == STDLIB_CONSTANT_FLOAT64_PINF ) {
					scale = STDLIB_CONSTANT_FLOAT64_PINF;
				} else if ( ax != 0.0 && scale != STDLIB_CONSTANT_FLOAT64_PINF ) {
					if ( scale < ax ) {
						r = scale / ax;
						sumsq = 1.0 + ( sumsq*r*r );
						scale = ax;
					} else {
						r = ax / scale;
						sumsq += r*r;
					}
				}
			}
		}
		if ( n == '1' && ( sum > value || stdlib_base_is_nan( sum ) ) ) {
			value = sum;
		}
	}
	if ( n == 'I' ) {
		for ( i = 0; i < M; i++ ) {
			sum = work[ offsetWork+(i*strideWork) ];
			if ( sum > value || stdlib_base_is_nan( sum ) ) {
				value = sum;
			}
		}
	} else if ( n == 'F' ) {
		value = scale * stdlib_base_sqrt( sumsq );
	}
	return value;
}
